  var panel=new DockPanel{Margin=new Thickness(24)};Content=panel;var head=new StackPanel();var headerScroll=new ScrollViewer{Content=head,MaxHeight=440,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};DockPanel.SetDock(headerScroll,Dock.Top);panel.Children.Add(headerScroll);
