  var fields=new StackPanel();fields.Children.Add(new TextBlock{Text="Name für diese Installation"});name.Text=session.DisplayName;name.IsReadOnly=session.Mode=="Test";fields.Children.Add(name);fields.Children.Add(other);other.Visibility=session.Mode=="Test"?Visibility.Collapsed:Visibility.Visible;other.Checked+=(_,_)=>{if(recorder!=null)recorder.CaptureOtherWindows=true;};other.Unchecked+=(_,_)=>{if(recorder!=null)recorder.CaptureOtherWindows=false;};head.Children.Add(fields);
